'use strict';

/**
 * runner-combined.js
 *
 * Runs the three combined configurations (generated by build-combined.js)
 * 50 times each and appends results to master-results.csv.
 *
 * Must be run AFTER:
 *   1. npm run benchmark  (OFAT runs complete)
 *   2. npm run analyse    (descriptive stats produced)
 *   3. npm run build-combined  (combined-config.js generated)
 *
 * Usage:
 *   npm run benchmark-combined
 *   (Server must be running: npm start)
 */

const puppeteer  = require('puppeteer');
const fs         = require('fs');
const path       = require('path');
const { configToQueryString } = require('./ofat-config');

const RUNS_PER_CONFIG       = 50;
const BASE_URL              = process.env.BASE_URL || 'http://localhost:3000';
const RESULTS_DIR           = path.join(__dirname, '../results');
const DELAY_BETWEEN_RUNS_MS = 800;

const LIGHTHOUSE_FLAGS = {
  output:         'json',
  logLevel:       'error',
  onlyCategories: ['performance'],
};

const LIGHTHOUSE_CONFIG = {
  extends: 'lighthouse:default',
  settings: {
    throttlingMethod: 'provided',
    throttling: {
      rttMs: 0, throughputKbps: 0, cpuSlowdownMultiplier: 1,
      requestLatencyMs: 0, downloadThroughputKbps: 0, uploadThroughputKbps: 0,
    },
    formFactor:      'desktop',
    screenEmulation: { mobile: false, width: 1350, height: 940, deviceScaleFactor: 1, disabled: false },
  },
};

function escapeCSV(val) {
  const s = String(val ?? '');
  return s.includes(',') || s.includes('"') || s.includes('\n')
    ? `"${s.replace(/"/g, '""')}"` : s;
}

async function runCombined() {
  const combinedConfigPath = path.join(__dirname, 'combined-config.js');
  if (!fs.existsSync(combinedConfigPath)) {
    console.error('combined-config.js not found. Run: npm run build-combined first.');
    process.exit(1);
  }

  const { COMBINED_EXPERIMENTS } = require('./combined-config');
  console.log(`\nCombined configurations loaded: ${COMBINED_EXPERIMENTS.length}`);
  console.log(`Runs per configuration: ${RUNS_PER_CONFIG}\n`);

  // Write to a timestamped results file so analyse.js can find and merge it
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
  const outputCsvPath = path.join(RESULTS_DIR, `results-combined-${timestamp}.csv`);
  const CSV_HEADER = 'factor,label,run,ttfb_ms,fcp_ms,speed_index_ms,lcp_ms,tbt_ms,cls,audit_duration_ms,config_duration_s,url\n';
  fs.writeFileSync(outputCsvPath, CSV_HEADER);
  console.log(`Output: ${outputCsvPath}`);
  const startTime   = Date.now();
  const timingLines = [];

  const executablePath = puppeteer.executablePath();
  const browser    = await puppeteer.launch({ headless: true, executablePath, args: ['--no-sandbox', '--disable-setuid-sandbox'] });
  const wsEndpoint = browser.wsEndpoint();
  const portMatch  = wsEndpoint.match(/:(\d+)\//);
  if (!portMatch) { await browser.close(); throw new Error(`Cannot extract port from: ${wsEndpoint}`); }
  const port = parseInt(portMatch[1]);
  console.log(`Browser on port ${port}`);

  try {
    for (let expIdx = 0; expIdx < COMBINED_EXPERIMENTS.length; expIdx++) {
      const exp = COMBINED_EXPERIMENTS[expIdx];
      const { factor, label, config } = exp;
      const qs  = configToQueryString(config);
      const url = `${BASE_URL}/?${qs}`;

      console.log(`\n[${expIdx + 1}/${COMBINED_EXPERIMENTS.length}] ${label}`);
      const configStart = Date.now();

      for (let run = 1; run <= RUNS_PER_CONFIG; run++) {
        const auditStart = Date.now();
        try {
          const { default: lighthouse } = await import('lighthouse');
          const { lhr } = await lighthouse(url, { ...LIGHTHOUSE_FLAGS, port }, LIGHTHOUSE_CONFIG);
          const auditMs = Date.now() - auditStart;

          const ttfb = Math.round((lhr.audits['server-response-time']?.numericValue ?? 0) * 10) / 10;
          const fcp  = Math.round((lhr.audits['first-contentful-paint']?.numericValue ?? 0) * 10) / 10;
          const si   = Math.round((lhr.audits['speed-index']?.numericValue ?? 0) * 10) / 10;
          const lcp  = Math.round((lhr.audits['largest-contentful-paint']?.numericValue ?? 0) * 10) / 10;
          const tbt  = Math.round((lhr.audits['total-blocking-time']?.numericValue ?? 0) * 10) / 10;
          const cls  = Math.round((lhr.audits['cumulative-layout-shift']?.numericValue ?? 0) * 10000) / 10000;
          const configDurationS = ((Date.now() - configStart) / 1000).toFixed(1);

          const row = [factor, label, run, ttfb, fcp, si, lcp, tbt, cls, auditMs, configDurationS, url]
            .map(escapeCSV).join(',') + '\n';
          fs.appendFileSync(outputCsvPath, row);

          process.stdout.write(`  Run ${run}/${RUNS_PER_CONFIG} — TTFB: ${ttfb}ms | FCP: ${fcp}ms | SI: ${si}ms | LCP: ${lcp}ms | TBT: ${tbt}ms | CLS: ${cls} (${auditMs}ms)\n`);
        } catch (err) {
          console.error(`  Run ${run} FAILED: ${err.message}`);
        }
        if (run < RUNS_PER_CONFIG) await new Promise(r => setTimeout(r, DELAY_BETWEEN_RUNS_MS));
      }

      const configDurationTotal = ((Date.now() - configStart) / 1000).toFixed(1);

      // Per-config metric summary
      const validRows = [];
      const allRows = fs.readFileSync(outputCsvPath, 'utf8').trim().split('\n').slice(1);
      allRows.forEach(line => {
        const cols = line.split(',');
        if (cols[1]?.replace(/"/g,'').trim() === label) {
          const lcp = parseFloat(cols[6]);
          if (!isNaN(lcp) && lcp >= 0) validRows.push({
            ttfb: parseFloat(cols[3]), fcp: parseFloat(cols[4]),
            si: parseFloat(cols[5]), lcp, tbt: parseFloat(cols[7]), cls: parseFloat(cols[8])
          });
        }
      });
      if (validRows.length > 0) {
        const avg = key => (validRows.reduce((s, r) => s + r[key], 0) / validRows.length).toFixed(1);
        console.log(`  Summary (n=${validRows.length})`);
        console.log(`  TTFB: ${avg('ttfb')}ms | FCP: ${avg('fcp')}ms | SI: ${avg('si')}ms`);
        console.log(`  LCP:  ${avg('lcp')}ms  | TBT: ${avg('tbt')}ms | CLS: ${avg('cls')}`);
      }

      timingLines.push(`${label}: ${configDurationTotal}s`);
      console.log(`[DONE ${expIdx + 1}/${COMBINED_EXPERIMENTS.length}] ${label} — ${configDurationTotal}s`);
    }
  } finally {
    await browser.close();
  }

  const totalDurationS = ((Date.now() - startTime) / 1000).toFixed(1);
  timingLines.push('');
  timingLines.push(`Total benchmark duration: ${totalDurationS}s`);
  timingLines.push(`Output CSV: ${path.basename(outputCsvPath)}`);
  const timingPath = path.join(RESULTS_DIR, `timing-combined-${timestamp}.txt`);
  fs.writeFileSync(timingPath, timingLines.join('\n') + '\n');

  console.log(`\n✓ Combined benchmark complete.`);
  console.log(`  Results: ${outputCsvPath}`);
  console.log(`  Timing:  ${timingPath}`);
  console.log(`  Total duration: ${totalDurationS}s`);
  console.log(`\nNext step: npm run analyse\n`);
}

runCombined().catch(err => { console.error(err); process.exit(1); });
